/**
 * Define an ordering relation on arrows with their instantiations. That is,
 * is candidate1 more specific than candidate2?
 */
def moreSpecificCandidate(candidate1: AppCandidate,
  candidate2: AppCandidate)(implicit coercions: CoercionOracle): Boolean = {

  val AppCandidate(SArrowType(_, domain1, range1, _, _, mi1), _, args1, _, _) = candidate1
  val AppCandidate(SArrowType(_, domain2, range2, _, _, mi2), _, args2, _, _) = candidate2

  // If these are dotted methods, add in the self type as an implicit first
  // parameter. The new domains will be a tuple of the form
  // `(selfType, domainType)`.
  val (newDomain1, newDomain2) = (mi1, mi2) match {
    case (Some(SMethodInfo(selfType1, -1)),
      Some(SMethodInfo(selfType2, -1))) =>
      (getDomainAndSelfType(candidate1.arrow),
        getDomainAndSelfType(candidate2.arrow))
    case _ => (domain1, domain2)
  }

  // Determine if a coercion occurred.
  val coercion1 = args1.exists(_.isInstanceOf[CoercionInvocation])
  val coercion2 = args2.exists(_.isInstanceOf[CoercionInvocation])

  // If one did not use coercions and the other did, the one without coercions
  // is more specific.
  (coercion1, coercion2) match {
    case (true, false) => false
    case (false, true) => true
    case _ => coercions.moreSpecific(newDomain1, newDomain2)
  }
}

/**
 * Determines if the given overloading is dynamically applicable.
 */
def isDynamicallyApplicable(overloading: Overloading,
  bestArrow: ArrowType,
  unliftedSargs: List[StaticArg],
  liftedSargs: List[StaticArg])(implicit analyzer: TypeAnalyzer): Option[Overloading] = {

  val SOverloading(ovInfo, ovName, origName, Some(ovType), schema) = overloading
  var newOvType: ArrowType = ovType
  val bestArrowDomainAndSelfType = getDomainAndSelfType(bestArrow)

  // If unlifted static args, then instantiate the unlifted static params.
  if (!unliftedSargs.isEmpty)
    newOvType = staticInstantiation(unliftedSargs, newOvType)
      .getOrElse(return None).asInstanceOf[ArrowType]

  // If there were lifted, inferred static args, then instantiate those.
  if (!liftedSargs.isEmpty)
    newOvType = staticInstantiation(liftedSargs,
      newOvType,
      applyLifted = true,
      applyUnlifted = false)
      .getOrElse(return None).asInstanceOf[ArrowType]

  // If there are still some static params in it, then we can't infer them
  // so it's not applicable. If this is not a subtype of the best arrow, then
  // it cannot be picked at runtime.
  if (hasStaticParams(newOvType) ||
    !isSubtype(getDomainAndSelfType(newOvType),
      bestArrowDomainAndSelfType))
    return None

    Some(SOverloading(ovInfo, ovName, origName, Some(newOvType), schema))
  }

  /**
   * Given an applicand and all the application candidates, return the applicand
   * updated with the dynamically applicable overloadings, arrow type, and
   * static args.
   */
  def rewriteApplicand(fn: Expr,
            candidates: List[AppCandidate],
            skipOverloads: Boolean)(implicit analyzer: TypeAnalyzer): Expr = {

    // Pull out the info for the winning candidate.
    val sma@AppCandidate(bestArrow, bestSargs, _, bestOverloading, bestFnl) = candidates.head

    fn match {
      case fn: FunctionalRef =>

        // Get the unlifted static args.
        val (liftedSargs, unliftedSargs) = bestSargs.partition(_.isLifted)


        // Get the dynamically applicable overloadings. Any time this method is
        // called, the candidates would have been created with corresponding
        // Overloading nodes; so use those instead of the ones on fn.
        val pruned = pruneMethodCandidates(candidates, sma)
        val overloadings = if (skipOverloads)  Nil else pruned.flatMap { c =>
          c.overloading.flatMap { o =>
            isDynamicallyApplicable(o, bestArrow, unliftedSargs, liftedSargs)
          }
....
      // parameter that could have made this applicable.
      case ((Right(_), None), _) =>
        return errorFactory.makeNotApplicableError(originalArrow, newArgsAndErrors.map(_._1))

      case ((Left(_), _), _) => None
    }
    errorFactory.makeFnInferenceError(originalArrow, fnErrors)
  }

  /**
   * Type check the application of the given arrow candidates to the given arg.
   * This returns the statically applicable candidates (with their corresponding
   * inferred static args and updated arguments) with the most specific one at
   * the head. The resulting AppCandidates will contain the single arg as a
   * singleton list.
   */
  def checkApplication(preCandidates: List[PreAppCandidate],
                       arg: Expr,
                       context: Option[Type])
                      (implicit errorFactory: ApplicationErrorFactory)
                       : Option[List[AppCandidate]] = {

    // Check the application using the args extrapolated from arg.
    val args = getArgList(arg)
    checkApplication(preCandidates, args, context) map { candidates =>

      // Combine the separated args back into a single arg in the resulting app
      // candidate.
      candidates.map(_.mergeArgs(NU.getSpan(arg)))
    }

  }

  /**
   * Type check the application of the given arrow candidates to the given args.
   * This returns the statically applicable candidates (with their corresponding
   * inferred static args and updated arguments) with the most specific one at
   * the head.
   */
  def checkApplication(preCandidates: List[PreAppCandidate],
                       iargs: List[Expr],
                       context: Option[Type],
                       mOpName: Option[Op] = None)
                      (implicit errorFactory: ApplicationErrorFactory)
                       : Option[List[AppCandidate]] = {

    // Check all the checkable args and make sure they all have types.
    val args = partitionArgs(iargs).getOrElse(return None)

    // Filter the overloadings that are applicable.
    val es = preCandidates.map(pc => checkApplicable(pc, context, args, mOpName))
    val (candidates, overloadingErrors) =
        (for (Left(x) <- es) yield x, for (Right(x) <- es) yield x)

    // If there were no candidates, report errors.
    if (candidates.isEmpty) {
      errors.signal(errorFactory.makeApplicationError(overloadingErrors))
      return None
    }

    // Sort the arrows and instantiations to find the statically most
    // applicable. Then update each candidate's Overloading node.
    val sorted = Some(candidates.sortWith(moreSpecificCandidate))
    // ensure that head is actually more specific.

    // An overloading more specific than every candidate, whose size the call
    // does not fix, makes the call an error.
    val unfixed = overloadingErrors.filter {
      case NoContextError(_, _, Some(u)) => candidates.forall(moreSpecificCandidate(u, _))
      case _ => false
    }
    if (!unfixed.isEmpty) {
      errors.signal(errorFactory.makeApplicationError(unfixed))
      return None
    }

    sorted
  }

  /**
   * Given a receiver type and a method name, return the list of all the arrow types for each
   * method overloading. Ignores any arrows that were for getters or setters.
   */
  def getCandidatesForMethod(recvrType: Type,
                             name: IdOrOp,
                             sargs: List[StaticArg],
                             loc: HasAt): Option[List[PreAppCandidate]] = {
    def noGetterSetter(m: Method): Option[Method] = m match {
      case g:FieldGetterMethod => None
      case s:FieldSetterMethod => None
      case m => Some(m)
    }
    val methods = findMethodsInTraitHierarchy(name, recvrType).toList.flatMap(noGetterSetter)
    var arrowsAndSchemataAndMethods = methods.flatMap{ m =>
      (makeArrowFromFunctional(m), makeArrowFromFunctional(m.originalMethod)) match {
        case (Some(s), Some(t)) => Some((s,t,m))
        case _ => None
      }
    }
    // Make sure all of the functions had return types declared or inferred
    // TODO: This could be handled more gracefully
    if (arrowsAndSchemataAndMethods.size != methods.size) {
      signal(loc, "The return type for %s could not be inferred".format(name))
      return None
    }

    // Instantiate the arrows if you were given static args
    if (!sargs.isEmpty) {
      arrowsAndSchemataAndMethods = arrowsAndSchemataAndMethods.
        flatMap(a => staticInstantiationForApp(sargs, a._1).
            map(x => (x.asInstanceOf[ArrowType],a._2, a._3)))
    }

    // Methods have no Overloading nodes.
    Some(arrowsAndSchemataAndMethods.map(a => PreAppCandidate(a._1, 
        Some(SOverloading(a._1.getInfo, name, name, Some(a._1), Some(a._2))), Some(a._3))))
  }

  /**
   * Given an applicand, return the list of all arrow type candidates for each
   * overloading.
   */
  def getCandidatesForFunction(fn: Expr, loc: HasAt): Option[List[PreAppCandidate]] = {
    TypeError.b1(fn);
    val fnType = getType(fn).getOrElse(return None)
    if (!isArrows(fnType)) {
      signal(loc, "Applicand has a type that is not an arrow: %s".format(normalize(fnType)))
      return None
    }
    Some(fn match {
      case f:FunctionalRef =>
        toListFromImmutable(f.getNewOverloadings).map { ov =>
          // The fn has already been type checked, so each overloading has an
          // arrow type.
          val arrow = ov.getType.get.asInstanceOf[ArrowType]
          PreAppCandidate(arrow, Some(ov), None) //DRC break here, None is wrong
        }
      case _ =>
        conjuncts(fnType).toList.map { t =>
          val arrow = t.asInstanceOf[ArrowType]
          PreAppCandidate(arrow, None, None) //DRC break here, None is wrong
        }
    })
  }

